from collections import defaultdict

class UndirectedGraph:

	def __init__(self, node_num):
		self.node_num = node_num
		self.graph = defaultdict(list)

	def add_edge(self, v, w):
		self.graph[v].append(w)
		self.graph[w].append(v)

	def _find(self, v, visited, deleted):
		stack = [v]
		parent = defaultdict(int)
		while stack:
			v = stack.pop()
			for next_v in self.graph[v]:
				if next_v == parent[v]:
					continue
				if visited[next_v]:
					path = [v]
					while next_v != v:
						v = parent[v]
						path.append(v)
					return path
				if next_v not in deleted:
					parent[next_v] = v
					stack.append(next_v)
			visited[v] = True
		return None

	def find_cycle(self, del_nodes):
		visited = [False] * (self.node_num + 1)
		deleted = set(del_nodes)
		for i in self.graph:
			if not visited[i] and i not in deleted:
				cycle = self._find(i, visited, deleted)
				if cycle:
					return cycle
		return []
